bigInv=require("fbc.mega_inventory")function peripheral.allOfType(a)return peripheral.find(a,function(b,c)return peripheral.hasType(c,"inventory")or false end)end;chest=bigInv.new(peripheral.allOfType("inventory"))if not chest then error("Error loading inventories: did you actually connect the chests to the computer?")end;local d=chest;function d:getItemDetailSafe(e)local f,g=pcall(d.getItemDetail,self,e)if f and g then return g else return nil end end;d.indexer={}d.indexer.defaultMaxCount=64;d.indexer.isIndexed=false;d.indexer.latestLog={}d.indexer.itemTypes={}function d.itemTypesCount()local h=0;for i in pairs(d.indexer.itemTypes)do h=h+1 end;return h end;function d.indexer.index()d.indexer.isIndexed=false;d.indexer.latestLog={"starting indexing ..."}local j=d.itemTypesCount()local k=d:list()for l,m in ipairs(k)do if m and not d.indexer.itemTypes[m.name]then local g=d:getItemDetailSafe(l)if g then d.indexer.itemTypes[m.name]={name=m.name,displayName=g.displayName,maxCount=g.maxCount}end;sleep(0)end;table.insert(d.indexer.latestLog,"indexing: "..math.floor(l/#k*100).."%")end;if d.itemTypesCount()>j then table.insert(d.indexer.latestLog,"saving index ...")if d.indexer.save()then table.insert(d.indexer.latestLog,"saved index successfully.")else table.insert(d.indexer.latestLog,"failted to saved index, probably no storage remaining.")end end;d.indexer.isIndexed=true;table.insert(d.indexer.latestLog,"indexed "..d.itemTypesCount().." unique items successfully.")end;function d.indexer:indexSlot(e)local g=d:getItemDetailSafe(e)if g and not d.indexer.itemTypes[g.name]then d.indexer.itemTypes[g.name]={name=g.name,displayName=g.displayName,maxCount=g.maxCount}return g end end;d.indexer.savePath=".indexedDB"function d.indexer.save()print("[items indexer] saving index to disk ...")local n=fs.open(d.indexer.savePath,"w+")if not n then print("[items indexer] failed to save index.")return false end;n.write(textutils.serialise(d.indexer.itemTypes,{allow_repetitions=false,compact=true}))n.close()print("[items indexer] saved index to disk.")return true end;function d.indexer.load()d.indexer.isIndexed=false;print("[items indexer] loading index from disk ...")if not fs.exists(d.indexer.savePath)then print("[items indexer] failed to load index: not found.")return false end;local n=fs.open(d.indexer.savePath,"r")if not n then print("[items indexer] failed to load index: not sure.")return false end;d.indexer.itemTypes=textutils.unserialise(n.readAll()or"")or{}print("[items indexer] loaded "..d.itemTypesCount().." items into index.")n.close()d.indexer.isIndexed=true;return true end;function d.count()local h=0;for l,m in ipairs(d:list())do if m~=nil and m.count~=nil then h=h+m.count end end;return h end;function d.maxCount()local k=d:list()local o=d:size()local h=0;for l,m in ipairs(k)do if m then if d.indexer.itemTypes[m.name]then h=h+d.indexer.itemTypes[m.name].maxCount else local g=d.indexer:indexSlot(l)if g then h=h+(g.maxCount or d.indexer.defaultMaxCount)else h=h+d.indexer.defaultMaxCount end;sleep(0)end else h=h+d.indexer.defaultMaxCount end;o=o-1 end;return h+o*d.indexer.defaultMaxCount end;function d.percentage()return math.floor(d:count()/d.maxCount()*100)end;return d
